 const nativeCommon146=id==='battery'?bench.targets.get('terminalR'):bench.group.getObjectByName('sr146_common'),common=nativeCommon146||new THREE.Group();if(!nativeCommon146){common.name='COM del banco virtual143';common.position.set(-.78,-.36,-.08);bench.group.add(common);
 const jack=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,.025,32),new THREE.MeshStandardMaterial({color:'#b7bdbc',metalness:.85,roughness:.32}));jack.rotation.x=Math.PI/2;jack.position.z=-.0275;common.add(jack);const recess=new THREE.Mesh(new THREE.CircleGeometry(.011,24),new THREE.MeshStandardMaterial({color:'#1d2727',roughness:.8,side:THREE.DoubleSide}));recess.position.z=-.0402;common.add(recess);
}
